// docs/failure-taxonomy.md, written from the taxonomy report. Pure: the
// report in, the file's text out. No date in it, so the dashboard can tell
// whether the file still matches what it shows. Regenerated by
// `pnpm taxonomy`; never edited by hand.
import { pct } from "../stats/format";
import type { Estimate } from "../stats/stats";
import type { CategoryRow, TaxonomyReport } from "./report";
import type { Note, Taxonomy } from "./schema";

const isNum = (x: number) => !Number.isNaN(x);
export const shareText = (e: Estimate) => (isNum(e.value) ? `${pct(e.value)} (${isNum(e.lo) ? `${(e.lo * 100).toFixed(1)}–${(e.hi * 100).toFixed(1)}` : "–"})` : "–");
export const trialPath = (n: Pick<Note, "runId" | "taskId" | "tryNumber">) => `/runs/${n.runId}/${n.taskId}/${n.tryNumber}`;

// Said wherever the counts are, so drafted notes are never read as a person's.
export const draftedLine = (report: TaxonomyReport): string | null =>
  report.drafted > 0 ? `${report.drafted} of the ${report.notes} notes, and their categories, were drafted by a model (Claude) reading the trajectories, not written by a person.` : null;

// The line the phase is for: what to fix first, and whether that's settled.
export function verdictLine(report: TaxonomyReport): string {
  const top = report.top;
  if (top === null) return "No agent failure is tagged yet, so there's nothing to fix first.";
  const lead = `Fix first: **${top.row.name}**, ${top.row.count} of ${report.tagged} tagged failures, ${shareText(top.row.share)}.`;
  if (top.next === null) return `${lead} No other agent-failure category has a tagged note.`;
  return top.clear
    ? `${lead} Its interval is clear of the next one, ${top.next.name} (${shareText(top.next.share)}).`
    : `${lead} Its interval overlaps the next one, ${top.next.name} (${shareText(top.next.share)}), so the order between the two is within the noise; it's first by count.`;
}

const cell = (s: string) => s.replace(/\|/g, "\\|").replace(/\s*\n\s*/g, " ");

function exampleLines(r: CategoryRow): string[] {
  if (r.examples.length === 0) return ["No tagged notes."];
  return r.examples.map((n) => `- \`${n.runId}\` / \`${n.taskId}\`, try ${n.tryNumber} (dashboard: \`${trialPath(n)}\`): ${cell(n.note)}`);
}

export function taxonomyDoc(o: { report: TaxonomyReport; taxonomy: Taxonomy }): string {
  const { report, taxonomy } = o;
  const L: string[] = [];
  L.push("# Failure taxonomy", "", "Generated by `pnpm taxonomy` from `evals/review/`. Don't edit it by hand; rerun the command.", "");
  L.push(verdictLine(report), "");
  L.push(
    `${report.notes} failed dev tries reviewed, from ${report.tasks} tasks; ${report.tagged} tagged.${report.untagged.length > 0 ? ` **${report.untagged.length} not tagged yet**, counted nowhere.` : ""}`,
    "",
    ...(draftedLine(report) === null ? [] : [`**${draftedLine(report)}**`, ""]),
    `Taxonomy written ${taxonomy.writtenAt}. Each note was written in free text first and given exactly one category afterwards; where two fitted, the one that happened first in the trajectory.`,
    "",
    "Share is of every tagged failure, with a 95% interval from the bootstrap: the notes are resampled 10,000 times by whole task (tries of one task fail alike), with a fixed seed. \"The task was wrong\" isn't an agent failure: those tasks get fixed, with a new dataset version.",
    "",
  );
  L.push("| category | failures | tasks | share | definition |", "|---|---:|---:|---|---|");
  for (const r of report.rows) L.push(`| ${cell(r.name)}${r.agentFailure ? "" : " (not an agent failure)"} | ${r.count} | ${r.tasks} | ${shareText(r.share)} | ${cell(r.definition)} |`);
  L.push("");
  L.push("## Examples", "");
  for (const r of report.rows) L.push(`### ${r.name}`, "", ...exampleLines(r), "");
  return `${L.join("\n").trimEnd()}\n`;
}
